{
  "name": "ms",
  "version": "4.0.0",
  "description": "Tiny millisecond conversion utility",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/vercel/ms.git"
  },
  "types": "./dist/index.d.ts",
  "type": "module",
  "exports": {
    ".": {
      "import": {
        "types": "./dist/index.d.ts",
        "default": "./dist/index.js"
      },
      "default": "./dist/index.js"
    }
  },
  "sideEffects": false,
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
	"packageManager": "pnpm@10.33.0+sha512.10568bb4a6afb58c9eb3630da90cc9516417abebd3fabbe6739f0ae795728da1491e9db5a544c76ad8eb7570f5c4bb3d6c637b2cb41bfdcdb47fa823c8649319",
  "files": [
    "dist"
  ],
  "scripts": {
    "test": "pnpm run test:nodejs && pnpm run test:edge",
    "test:nodejs": "jest --env node",
    "test:edge": "jest --env @edge-runtime/jest-environment --no-coverage",
    "build": "tsdown",
    "lint": "biome lint",
    "format": "biome format",
    "typecheck": "tsc --noEmit",
    "attw": "pnpm build && attw --pack --profile esm-only .",
    "precommit": "lint-staged",
    "prepare": "husky"
  },
  "devDependencies": {
    "@arethetypeswrong/cli": "0.18.2",
    "@biomejs/biome": "2.1.3",
    "@edge-runtime/jest-environment": "4.0.0",
    "@jest/globals": "30.0.5",
    "@types/node": "^24.1.0",
    "husky": "9.1.7",
    "jest": "30.0.5",
    "lint-staged": "16.1.2",
    "ts-jest": "29.4.0",
    "tsdown": "^0.13.0",
    "typescript": "5.8.3"
  }
}
